package com.ragpipeline.kafka;import com.ragpipeline.model.*;import com.ragpipeline.repository.*;import com.ragpipeline.service.*;import lombok.RequiredArgsConstructor;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Service;@Service @RequiredArgsConstructor public class IngestionConsumer{private final DocumentRepository docs;private final ChunkingService chunking;private final ChunkRepository chunks;private final DocumentIngestionService ingestion;private final EmbeddingService embedding;@KafkaListener(topics="${kafka.topics.ingestion-requests}")public void consume(IngestionJob j){Document d=docs.findById(j.getDocumentId()).orElseThrow();d.setStatus("PROCESSING");docs.save(d);try{var created=chunks.saveAll(chunking.chunk(d,j.getChunkingStrategy()));embedding.embedAndStore(created);ingestion.markIndexed(d.getId());}catch(Exception e){d.setStatus("FAILED");docs.save(d);throw e;}}}
